import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type SlideClosingCopy = { heading: string; body?: string; contact?: string }

export function SlideClosing({ copy, medium = "web" }: { copy: SlideClosingCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <section data-slot="slide-closing" data-medium={medium} className={cn("flex flex-col items-center justify-center gap-8 bg-primary text-center text-primary-foreground", slide ? "aspect-video w-full overflow-hidden px-24 py-20" : "px-6 py-20 md:px-12")}>
      <h2 className={cn("font-heading font-semibold tracking-tight", slide ? "text-7xl" : "text-4xl")}>{copy.heading}</h2>
      {copy.body ? <p className={cn("max-w-3xl opacity-90", slide ? "text-3xl" : "text-lg")}>{copy.body}</p> : null}
      {copy.contact ? <p className={cn("font-medium", slide ? "text-2xl" : "text-base")}>{copy.contact}</p> : null}
    </section>
  )
}
